>#Section 3. React state
>看一下React实现时钟的例子：
>
    import React from 'react';
    import ReactDOM from 'react-dom';
    function tick() {
	  const element = (
	    <div>
	      <h1>Hello, world!</h1>
	      <h2>It is {new Date().toLocaleTimeString()}.</h2>
	    </div>
	  );
	  ReactDOM.render(
	    element,
	    document.getElementById('root')
	  );
	}
>	
	setInterval(tick, 1000);
